{"content":""""Linear-algebra attack on the custom stream cipher (cipher.py)."""
import numpy as np

from cipher import StreamCipher


def _solve_gf2(M, y):
    """Solve M @ x = y over GF(2). M: (n, m), y: (n,). Returns one solution (free vars=0) or None if inconsistent."""
    M = np.array(M, dtype=int) % 2
    y = np.array(y, dtype=int).reshape(-1) % 2
    n, m = M.shape
    A = np.concatenate([M, y.reshape(-1, 1)], axis=1).astype(int)
    where = [-1] * m
    row = 0
    for col in range(m):
        sel = -1
        for i in range(row, n):
            if A[i, col]:
                sel = i
                break
        if sel == -1:
            continue
        A[[row, sel]] = A[[sel, row]]
        where[col] = row
        for i in range(n):
            if i != row and A[i, col]:
                A[i] ^= A[row]
        row += 1
    for i in range(row, n):
        if A[i, m]:
            return None
    x = np.zeros(m, dtype=int)
    for j in range(m):
        if where[j] != -1:
            x[j] = A[where[j], m]
    return np.array(x, dtype=np.uint8)


def _keystream_bits_for_key(key, nbits):
    nbytes = (nbits + 7) // 8
    ks = StreamCipher(np.array(key, dtype=np.uint8)).encrypt(bytes(nbytes))
    bits = []
    for b in ks:
        for k in range(8):
            bits.append((b >> (7 - k)) & 1)
    return bits[:nbits]


def attack(known_pairs):
    """Recover an equivalent secret key from known plaintext-ciphertext pairs.

    Args:
        known_pairs: list of (plaintext_bytes, ciphertext_bytes) tuples.

    Returns:
        numpy.ndarray of 8 uint8 integers that decrypts the ciphertexts.
    """
    if not known_pairs:
        return np.zeros(8, dtype=np.uint8)

    # Derive keystream from pairs; use the longest pair (all pairs restart
    # from the same initial state, so they must share a common prefix).
    keystreams = []
    for pt, ct in known_pairs:
        pt = bytes(pt)
        ct = bytes(ct)
        if len(pt) != len(ct):
            raise ValueError("plaintext/ciphertext length mismatch")
        keystreams.append(bytes(a ^ b for a, b in zip(pt, ct)))
    keystreams.sort(key=len, reverse=True)
    # Consistency check: shorter keystreams must be prefixes of the longest.
    longest = keystreams[0]
    for ks in keystreams[1:]:
        if longest[: len(ks)] != ks:
            # Inconsistent (should not happen for this cipher); fall back to
            # using the longest only. Brute-force verification below guards us.
            pass

    nbits = len(longest) * 8
    if nbits == 0:
        return np.zeros(8, dtype=np.uint8)

    y = []
    for b in longest:
        for k in range(8):
            y.append((b >> (7 - k)) & 1)

    # Build linear map M: key (8 bits) -> keystream bits, column j from basis e_j.
    M = np.zeros((nbits, 8), dtype=int)
    for j in range(8):
        e = [0] * 8
        e[j] = 1
        M[:, j] = _keystream_bits_for_key(e, nbits)

    sol = _solve_gf2(M, y)
    if sol is not None:
        cand = np.array(sol, dtype=np.uint8)
        # Verify it reproduces all keystreams.
        ok = True
        for pt, ct in known_pairs:
            if StreamCipher(cand).encrypt(bytes(pt)) != bytes(ct):
                ok = False
                break
        if ok:
            return cand

    # Fallback: brute force over 2**8 bit-keys (keystream space has only
    # 16 distinct values, so this always finds an equivalent key).
    for trial in range(256):
        cand = np.array([(trial >> (7 - i)) & 1 for i in range(8)], dtype=np.uint8)
        if all(StreamCipher(cand).encrypt(bytes(pt)) == bytes(ct) for pt, ct in known_pairs):
            return cand

    # Last resort (should be unreachable for bit-keys).
    return np.array(sol if sol is not None else [0] * 8, dtype=np.uint8)


def _load_pairs(path="/app/known_pairs.txt"):
    pairs = []
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            pt_hex, ct_hex = line.split(":")
            pairs.append((bytes.fromhex(pt_hex), bytes.fromhex(ct_hex)))
    return pairs


if __name__ == "__main__":
    pairs = _load_pairs()
    key = attack(pairs)
    print("Recovered key:", key.tolist())
    for pt, ct in pairs:
        dec = StreamCipher(key).encrypt(ct)
        print(pt, dec == pt)
